enum class CapabilityState {
    
    AVAILABLE,
    PERMISSION_REQUIRED,
    APPROVAL_REQUIRED,
    REGION_RESTRICTED,
    UNSUPPORTED;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeCapabilityState: FfiConverterRustBuffer<CapabilityState> {
    override fun read(buf: ByteBuffer) = try {
        CapabilityState.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: CapabilityState) = 4UL

    override fun write(value: CapabilityState, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}







/**
 * Stable, non-secret error codes for generated hosts.
 */
sealed class MobileBindingsException: kotlin.Exception() {
    
    class Closed(
        ) : MobileBindingsException() {
        override val message
            get() = ""
    }
    
    class InvalidRequest(
        ) : MobileBindingsException() {
        override val message
            get() = ""
    }
    
    class InvalidDatabaseKey(
        ) : MobileBindingsException() {
        override val message
            get() = ""
    }
    
    class WrongDatabaseKey(
        ) : MobileBindingsException() {
        override val message
            get() = ""
    }
    
    class Database(
        ) : MobileBindingsException() {
        override val message
            get() = ""
    }
    
    class UnsupportedSchema(
        ) : MobileBindingsException() {
        override val message
            get() = ""
    }
    
    class IdentityMismatch(
        ) : MobileBindingsException() {
        override val message
            get() = ""
    }
    
    class WrongPassphrase(
        ) : MobileBindingsException() {
        override val message
            get() = ""
    }
    
    class InvalidProfile(
        ) : MobileBindingsException() {
        override val message
            get() = ""
    }
    
    class Crypto(
        ) : MobileBindingsException() {
        override val message
            get() = ""
    }
    
    class Conflict(
        ) : MobileBindingsException() {
        override val message
            get() = ""
    }
    
    class NotFound(
        ) : MobileBindingsException() {
        override val message
